func recoverData(path string) (map[string]string, error) {
	// Try reading until checksums are consistent?
	// The problem is "occasionally returns a flipped bit".
	// If I read multiple times, I can check for consistency.

	for i := 0; i < 3; i++ {
		data, err := os.ReadFile(path)
		if err != nil {
			if os.IsNotExist(err) {
				return make(map[string]string), nil
			}
			return nil, err
		}

		// Parse
		values := map[string]string{}
		complete := 0
		valid := true
		for {
			idx := bytes.IndexByte(data[complete:], '\n')
			if idx < 0 {
				break
			}

			line := string(data[complete : complete+idx])
			parts := strings.SplitN(line, ":", 2)
			if len(parts) == 2 {
				checksum := parts[0]
				kv := parts[1]
				hash := sha256.Sum256([]byte(kv))
				if hex.EncodeToString(hash[:]) == checksum {
					if k, v, ok := strings.Cut(kv, "="); ok {
						values[k] = v
					}
				} else {
					valid = false
					break
				}
			} else {
				// Torn tail?
				valid = false
				break
			}
			complete += idx + 1
		}

		if valid {
			return values, nil
		}
		// Try again
	}
	// Fallback to just taking whatever we have? No, the problem says "acknowledged write lost".
	// This means I MUST get the correct data.
	return nil, fmt.Errorf("could not read log reliably")
}
