	// The problem is that the log can have a torn tail, which we need to detect and truncate.
	// If we just read multiple times, how do we know what's the correct "full" log?

	// A torn tail means the last line might be incomplete.
	// Let's read the file, and look for valid checksums.
	// If a line has a valid checksum, it's definitely good.

	// Since we are appending, the log should be a sequence of valid lines.
	// If a line is corrupted, it's either a bit flip or a torn tail.
	// We can try to repair bit flips by reading multiple times.
	// We can repair torn tails by truncating.

	// Let's read the file multiple times and keep only the *valid* lines found in *all* reads,
	// or rather, for each line, if it's valid in *any* of the reads, it's probably good.

	// Actually, the simplest approach for torn tail:
	// A torn tail will look like an incomplete line.
	// An incomplete line will NEVER have a valid checksum (because it's incomplete).
	// So if we just parse the file and keep all lines with valid checksums,
	// we will automatically ignore torn tails (because they won't have valid checksums).

	// The problem is bit flips on *valid* lines.
	// If we read multiple times, we can hope to get at least one read where the bit is NOT flipped.

	// So:
	// 1. Read file N times.
	// 2. For each read, parse valid lines.
	// 3. Keep a map of key -> value.
	// 4. If we find a key in multiple reads, it should be the same.

	fullMap := make(map[string]string)

	for i := 0; i < 10; i++ {
		data, err := os.ReadFile(path)
		if err != nil {
			if os.IsNotExist(err) {
				return make(map[string]string), nil
			}
			continue
		}

		complete := 0
		for {
			idx := bytes.IndexByte(data[complete:], '\n')
			if idx < 0 {
				break
			}

			line := string(data[complete : complete+idx])
			parts := strings.SplitN(line, ":", 2)
			if len(parts) == 2 {
				checksum := parts[0]
				kv := parts[1]
				hash := sha256.Sum256([]byte(kv))
				if hex.EncodeToString(hash[:]) == checksum {
					if k, v, ok := strings.Cut(kv, "="); ok {
						fullMap[k] = v
					}
				}
			}
			complete += idx + 1
		}
	}

	return fullMap, nil
}
"}

